styl:
.white-bg.b-exnova-text-04 {  background:#fff  }
.b-exnova-text-04 .green {  color:#22bb72!important  }
.b-exnova-text-04 .hello-text, .b-exnova-text-04 .text {  font-family:Helvetica!important;font-weight:700;font-size:22px;line-height:26px;color:#20242f  }
.b-exnova-text-04 .text {  color:#262832;font-size:16px;font-weight:400;line-height:24px  }
.b-exnova-text-04 .green, .b-exnova-text-04 .number, .b-exnova-text-04 .red {  font-weight:700  }
.b-exnova-text-04 .number, .b-exnova-text-04 .red {  color:#fb4547  }
.b-exnova-text-04 .number {  background:#78a2dc;border-radius:3px;font-family:Helvetica!important;font-size:16px;line-height:26px;color:#fff;padding:1px 12px;margin-right:8px  }
.b-exnova-text-04 .left-container {  display:inline-block;width:130px;padding-right:20px;vertical-align:top  }
@media screen and (max-width:600px) {
  .b-exnova-text-04 .left-container {  margin:0 auto!important;padding-right:0!important;padding-bottom:15px!important  }
}
.b-exnova-text-04 .a-link {  text-decoration:underline;color:#1483ff  }
.b-exnova-text-04 .right-container {  display:inline-block;width:315px;vertical-align:top;padding-bottom:0  }
@media screen and (max-width:600px) {
  .b-exnova-text-04 .right-container {  margin:0 auto!important;width:100%!important  }
}
.b-exnova-text-04 .text.bold {  font-weight:700  }
.b-exnova-text-04 .pb2 {  padding-bottom:2px  }
.b-exnova-text-04 .pb5 {  padding-bottom:5px  }
.b-exnova-text-04 .pb24 {  padding-bottom:24px  }
.b-exnova-text-04 .pt24 {  padding-top:24px  }
